// ---------------- Level data: World 1-1 ----------------
const LW = 224, LH = 15;
const TI = { EMPTY: 0, GROUND: 1, BRICK: 2, Q: 3, USED: 4, HARD: 5, PTL: 6, PTR: 7, PBL: 8, PBR: 9, HIDDEN: 11, MULTI: 13 };
const SOLID = new Set([1, 2, 3, 4, 5, 6, 7, 8, 9, 13]);
const World = {
  tiles: new Uint8Array(LW * LH),
  content: new Map(),      // idx -> 'coin' | 'mush' | 'star' | '1up'
  multiHits: new Map(),    // idx -> remaining coins
  enemySpawns: [],         // {tx, type, spawned}
  decor: { hills: [], bushes: [], clouds: [] },
  flagX: 198, castleX: 202,
};
const idx = (tx, ty) => ty * LW + tx;
function tileAt(tx, ty) {
  if (ty >= LH) return 0;
  if (ty < 0) return 0;
  if (tx < 0) return TI.HARD;
  if (tx >= LW) return 0;
  return World.tiles[idx(tx, ty)];
}
function setTile(tx, ty, v) { World.tiles[idx(tx, ty)] = v; }

function buildLevel() {
  const Wd = World;
  Wd.tiles.fill(0); Wd.content.clear(); Wd.multiHits.clear(); Wd.enemySpawns.length = 0;
  Wd.decor = { hills: [], bushes: [], clouds: [] };
  const ground = (a, b) => { for (let x = a; x <= b; x++) { setTile(x, 13, TI.GROUND); setTile(x, 14, TI.GROUND); } };
  const brick = (x, y) => setTile(x, y, TI.BRICK);
  const q = (x, y, c) => { setTile(x, y, TI.Q); Wd.content.set(idx(x, y), c); };
  const hidden = (x, y, c) => { setTile(x, y, TI.HIDDEN); Wd.content.set(idx(x, y), c); };
  const multi = (x, y) => { setTile(x, y, TI.MULTI); Wd.multiHits.set(idx(x, y), 10); };
  const starBrick = (x, y) => { setTile(x, y, TI.BRICK); Wd.content.set(idx(x, y), 'star'); };
  const pipe = (x, h) => { setTile(x, 13 - h, TI.PTL); setTile(x + 1, 13 - h, TI.PTR); for (let y = 14 - h; y <= 12; y++) { setTile(x, y, TI.PBL); setTile(x + 1, y, TI.PBR); } };
  const col = (x, h) => { for (let y = 13 - h; y <= 12; y++) setTile(x, y, TI.HARD); };
  const enemy = (tx, type) => Wd.enemySpawns.push({ tx, type, spawned: false });

  ground(0, 68); ground(71, 85); ground(89, 152); ground(155, LW - 1);
  q(16, 9, 'coin');
  brick(20, 9); q(21, 9, 'mush'); brick(22, 9); q(23, 9, 'coin'); brick(24, 9); q(22, 5, 'coin');
  pipe(28, 2); pipe(38, 3); pipe(46, 4); pipe(57, 4);
  hidden(64, 9, '1up');
  brick(77, 9); q(78, 9, 'mush'); brick(79, 9);
  for (let x = 80; x <= 87; x++) brick(x, 5);
  for (let x = 91; x <= 93; x++) brick(x, 5);
  q(94, 5, 'coin'); multi(94, 9);
  starBrick(100, 9); brick(101, 9);
  q(106, 9, 'coin'); q(109, 9, 'coin'); q(109, 5, 'mush'); q(112, 9, 'coin');
  brick(118, 9);
  for (let x = 121; x <= 123; x++) brick(x, 5);
  brick(128, 5); q(129, 5, 'coin'); q(130, 5, 'coin'); brick(131, 5); brick(129, 9); brick(130, 9);
  for (let i = 0; i < 4; i++) { col(134 + i, i + 1); col(140 + i, 4 - i); col(148 + i, i + 1); col(155 + i, 4 - i); }
  col(152, 4);
  pipe(163, 2);
  brick(168, 9); brick(169, 9); q(170, 9, 'coin'); brick(171, 9);
  pipe(179, 2);
  for (let i = 0; i < 8; i++) col(181 + i, i + 1);
  col(189, 8);
  col(Wd.flagX, 1);

  enemy(22, 'goomba'); enemy(40, 'goomba'); enemy(51, 'goomba'); enemy(52.5, 'goomba');
  enemy(80, 'goomba'); enemy(81.5, 'goomba'); enemy(97, 'goomba'); enemy(98.5, 'goomba');
  enemy(107, 'koopa'); enemy(114, 'goomba'); enemy(115.5, 'goomba');
  enemy(124, 'goomba'); enemy(125.5, 'goomba'); enemy(174, 'goomba'); enemy(175.5, 'goomba');

  for (let base = 0; base < LW; base += 48) {
    Wd.decor.hills.push({ x: base, big: true }, { x: base + 16, big: false });
    Wd.decor.clouds.push({ x: base + 8, y: 3, n: 1 }, { x: base + 19, y: 2, n: 1 }, { x: base + 27, y: 2, n: 3 }, { x: base + 36, y: 3, n: 2 });
    Wd.decor.bushes.push({ x: base + 11, n: 3 }, { x: base + 23, n: 1 }, { x: base + 41, n: 2 });
  }
}

// ---------------- Generic tile collision ----------------
// e: {x (center), y (feet), w, h, vx, vy}; returns flags
function isSolidAt(px, py, upward) {
  const tx = Math.floor(px / T), ty = Math.floor(py / T);
  const t = tileAt(tx, ty);
  if (SOLID.has(t)) return true;
  return upward && t === TI.HIDDEN;
}
function moveX(e) {
  e.x += e.vx;
  const hw = e.w / 2, top = e.y - e.h + 2, bot = e.y - 1;
  const mid = (top + bot) / 2;
  if (e.vx > 0) {
    const rx = e.x + hw - 1;
    if (isSolidAt(rx, top) || isSolidAt(rx, mid) || isSolidAt(rx, bot)) {
      e.x = Math.floor(rx / T) * T - hw; e.vx = 0; return 'right';
    }
  } else if (e.vx < 0) {
    const lx = e.x - hw;
    if (isSolidAt(lx, top) || isSolidAt(lx, mid) || isSolidAt(lx, bot)) {
      e.x = (Math.floor(lx / T) + 1) * T + hw; e.vx = 0; return 'left';
    }
  }
  return null;
}
function moveY(e) {
  e.y += e.vy;
  const hw = e.w / 2, l = e.x - hw + 1, r = e.x + hw - 2;
  if (e.vy >= 0) {
    if (isSolidAt(l, e.y) || isSolidAt(r, e.y)) {
      e.y = Math.floor(e.y / T) * T; e.vy = 0; return 'ground';
    }
  } else {
    const top = e.y - e.h;
    const hl = isSolidAt(l, top, true), hr = isSolidAt(r, top, true);
    if (hl || hr) {
      e.y = (Math.floor(top / T) + 1) * T + e.h; e.vy = 0;
      // which tile did we hit? prefer the one closer to center
      const tyy = Math.floor(top / T);
      let tx;
      if (hl && hr) { tx = Math.floor(e.x / T); }
      else tx = Math.floor((hl ? l : r) / T);
      return { hit: 'ceiling', tx, ty: tyy };
    }
  }
  return null;
}
function onGroundCheck(e) {
  const hw = e.w / 2;
  return isSolidAt(e.x - hw + 1, e.y) || isSolidAt(e.x + hw - 2, e.y);
}
//__NEXT__

// ---------------- Game state ----------------
const Game = {
  state: 'title', running: false, paused: false,
  score: 0, coins: 0, lives: 3, time: 400, timeAcc: 0,
  camX: 0, frame: 0, stateT: 0, hurry: false,
  entities: [], particles: [], bumps: [], popups: [],
  flag: { y: 0, done: false }, clearBonus: 0,
};
const mario = {
  x: 40, y: 13 * T, w: 12, h: 16, vx: 0, vy: 0, dir: 1,
  power: 0,            // 0 small, 1 big, 2 fire
  onGround: false, jumping: false, crouch: false, skid: false,
  invuln: 0, star: 0, anim: 0, animT: 0, dead: false, dieT: 0,
  growT: 0, shrinkT: 0, fireT: 0, fireballs: 0, pipeT: 0,
};
const PH = { walkAcc: 0.045, runAcc: 0.07, maxWalk: 1.55, maxRun: 2.6, friction: 0.06, skid: 0.16,
  gravUp: 0.19, gravDown: 0.5, termV: 4.5 };

function resetMario(full) {
  Object.assign(mario, { x: 40, y: 13 * T, vx: 0, vy: 0, dir: 1, onGround: false, jumping: false, crouch: false, skid: false,
    invuln: 0, star: 0, anim: 0, animT: 0, dead: false, dieT: 0, growT: 0, shrinkT: 0, fireT: 0, fireballs: 0, pipeT: 0 });
  if (full) mario.power = 0;
  mario.h = mario.power ? 32 : 16;
}
function startLevel() {
  buildLevel();
  Game.entities = []; Game.particles = []; Game.bumps = []; Game.popups = [];
  Game.camX = 0; Game.time = 400; Game.timeAcc = 0; Game.hurry = false; Audio.setHurry(false);
  Game.flag = { y: 3 * T + 8, done: false }; Game.clearBonus = 0;
  resetMario(false);
  setState('intro');
}
function setState(s) { Game.state = s; Game.stateT = 0; Game.running = (s === 'play'); }
function addScore(n, x, y) {
  Game.score += n;
  if (x !== undefined) Game.popups.push({ x, y, t: 0, text: String(n) });
}
function addCoin(x, y) {
  Game.coins++; Audio.sfx.coin(); addScore(200, x, y);
  if (Game.coins >= 100) { Game.coins -= 100; Game.lives++; Audio.sfx.oneup(); }
}
function addLife(x, y) { Game.lives++; Audio.sfx.oneup(); Game.popups.push({ x, y, t: 0, text: '1UP' }); }

// ---------------- Mario update ----------------
function jumpVel() {
  const s = Math.abs(mario.vx);
  return s < 1 ? -5.0 : s < 2.2 ? -5.2 : -5.5;
}
function updateMario() {
  const m = mario;
  if (m.growT > 0) { m.growT--; return; }
  if (m.shrinkT > 0) { m.shrinkT--; return; }
  if (m.invuln > 0) m.invuln--;
  if (m.star > 0) { m.star--; }
  if (m.fireT > 0) m.fireT--;

  const left = keys.left, right = keys.right;
  const run = keys.run;
  // crouch (big only)
  const wantCrouch = keys.down && m.power > 0 && m.onGround;
  if (wantCrouch && !m.crouch) { m.crouch = true; m.h = 16; }
  else if (!wantCrouch && m.crouch) {
    // stand up only if there's room
    const top = m.y - 32;
    if (!isSolidAt(m.x - 5, top) && !isSolidAt(m.x + 4, top)) { m.crouch = false; m.h = 32; }
  }

  // horizontal
  const acc = run ? PH.runAcc : PH.walkAcc;
  const max = run ? PH.maxRun : PH.maxWalk;
  m.skid = false;
  if (m.crouch && m.onGround) {
    m.vx = Math.abs(m.vx) <= PH.friction ? 0 : m.vx - Math.sign(m.vx) * PH.friction;
  } else if (left && !right) {
    if (m.vx > 0 && m.onGround) { m.vx -= PH.skid; m.skid = true; } else { m.vx -= m.onGround ? acc : acc * 0.8; }
    if (m.onGround) m.dir = -1;
  } else if (right && !left) {
    if (m.vx < 0 && m.onGround) { m.vx += PH.skid; m.skid = true; } else { m.vx += m.onGround ? acc : acc * 0.8; }
    if (m.onGround) m.dir = 1;
  } else if (m.onGround) {
    m.vx = Math.abs(m.vx) <= PH.friction ? 0 : m.vx - Math.sign(m.vx) * PH.friction;
  }
  const cap = m.onGround ? max : Math.max(max, Math.abs(m.vx));
  if (Math.abs(m.vx) > cap) m.vx = Math.sign(m.vx) * Math.max(cap, Math.abs(m.vx) - 0.05);

  // jump
  if (pressed.jump && m.onGround) {
    m.vy = jumpVel(); m.jumping = true; m.onGround = false;
    (m.power ? Audio.sfx.bigjump : Audio.sfx.jump)();
  }
  pressed.jump = false;
  // fire
  if (pressed.run && m.power === 2 && !m.crouch && m.fireballs < 2 && m.fireT === 0) {
    spawnFireball(m); m.fireT = 6; m.fireballs++;
  }
  pressed.run = false;

  // gravity
  const g = (m.vy < 0 && keys.jump && m.jumping) ? PH.gravUp : PH.gravDown;
  m.vy = Math.min(PH.termV, m.vy + g);
  if (m.vy >= 0) m.jumping = false;

  // move & collide
  moveX(m);
  const minX = Game.camX + 6;
  if (m.x < minX) { m.x = minX; if (m.vx < 0) m.vx = 0; }
  const r = moveY(m);
  if (r === 'ground') { m.onGround = true; m.jumping = false; }
  else { m.onGround = false; if (r && r.hit === 'ceiling') hitBlock(r.tx, r.ty, m); }

  // fell in a pit
  if (m.y > (LH + 1) * T) killMario(true);

  // anim
  if (!m.onGround) m.anim = 4;
  else if (Math.abs(m.vx) < 0.1) { m.anim = 0; m.animT = 0; }
  else {
    m.animT += Math.abs(m.vx) * 0.55 + 0.5;
    if (m.animT >= 6) { m.animT = 0; m.anim = m.anim >= 1 && m.anim < 3 ? m.anim + 1 : 1; }
    if (m.anim < 1 || m.anim > 3) m.anim = 1;
  }

  // flagpole
  if (!Game.flag.done && m.x + 4 >= World.flagX * T + 7 && m.x - 4 <= World.flagX * T + 9 && m.y > 3 * T && m.y <= 13 * T) {
    startFlag();
  }
}
function spawnFireball(m) {
  Audio.sfx.fire();
  Game.entities.push({ type: 'fireball', x: m.x + m.dir * 8, y: m.y - (m.crouch ? 6 : 18), w: 6, h: 6, vx: m.dir * 3.2, vy: 1.5, life: 0, anim: 0 });
}
function damageMario() {
  const m = mario;
  if (m.invuln > 0 || m.star > 0 || m.dead || m.growT || m.shrinkT) return;
  if (m.power > 0) {
    m.power = 0; m.shrinkT = 40; m.invuln = 150; m.h = 16; m.crouch = false;
    Audio.sfx.pipe();
  } else killMario(false);
}
function killMario(pit) {
  const m = mario;
  if (m.dead) return;
  m.dead = true; m.dieT = 0; m.vy = pit ? 0 : -5; m.vx = 0; m.power = 0; m.h = 16;
  Audio.sfx.die();
  setState('dying');
}
function powerUp(kind, x, y) {
  const m = mario;
  if (kind === '1up') { addLife(x, y); return; }
  if (kind === 'star') { m.star = 60 * 11; addScore(1000, x, y); Audio.sfx.powerup(); return; }
  addScore(1000, x, y); Audio.sfx.powerup();
  if (m.power === 0) { m.power = kind === 'flower' ? 1 : 1; m.growT = 40; m.h = 32; m.crouch = false; }
  else if (kind === 'flower' && m.power === 1) { m.power = 2; m.growT = 40; }
}
//__NEXT__

if (m.power === 0) {
  m.power = 1; m.growT = 40; m.h = 32; m.crouch = false;
  if (isSolidAt(m.x - 5, m.y - 31) || isSolidAt(m.x + 4, m.y - 31)) { m.crouch = true; m.h = 16; }
}
else if (kind === 'flower' && m.power === 1) { m.power = 2; m.growT = 40; }

// ---------------- Blocks ----------------
function hitBlock(tx, ty, byMario) {
  const t = tileAt(tx, ty), i = idx(tx, ty);
  const px = tx * T, py = ty * T;
  if (t === TI.Q || t === TI.HIDDEN) {
    const c = World.content.get(i) || 'coin';
    setTile(tx, ty, TI.USED); bump(tx, ty);
    if (c === 'coin') { spawnCoinPop(px, py); addCoin(px + 8, py); }
    else spawnItem(c, px, py);
  } else if (t === TI.MULTI) {
    let n = World.multiHits.get(i);
    spawnCoinPop(px, py); addCoin(px + 8, py); bump(tx, ty);
    n--; World.multiHits.set(i, n);
    if (n <= 0) setTile(tx, ty, TI.USED);
  } else if (t === TI.BRICK) {
    const c = World.content.get(i);
    if (c) { setTile(tx, ty, TI.USED); bump(tx, ty); spawnItem(c, px, py); World.content.delete(i); }
    else if (byMario && mario.power > 0) {
      setTile(tx, ty, TI.EMPTY); Audio.sfx.break(); addScore(50);
      for (const [dx, dy, vx, vy] of [[0, 0, -1, -4.5], [8, 0, 1, -4.5], [0, 8, -1, -2.5], [8, 8, 1, -2.5]])
        Game.particles.push({ kind: 'debris', x: px + dx, y: py + dy, vx, vy, t: 0 });
      killEnemiesOn(tx, ty);
    } else { bump(tx, ty); Audio.sfx.bump(); }
  } else {
    Audio.sfx.bump();
  }
}
function bump(tx, ty) {
  if (!Game.bumps.some(b => b.tx === tx && b.ty === ty)) Game.bumps.push({ tx, ty, t: 0 });
  killEnemiesOn(tx, ty);
}
function killEnemiesOn(tx, ty) {
  for (const e of Game.entities) {
    if (!isEnemy(e) || e.dead) continue;
    if (Math.abs(e.y - ty * T) <= 2 && e.x + e.w / 2 > tx * T && e.x - e.w / 2 < tx * T + T) flipKill(e, e.x < tx * T + 8 ? -1 : 1);
  }
  for (const e of Game.entities) { // shake off items too
    if (e.type === 'item' && Math.abs(e.y - ty * T) <= 2 && e.x > tx * T - 8 && e.x < tx * T + 24) e.vy = -3;
  }
}
function spawnCoinPop(px, py) {
  Game.particles.push({ kind: 'coin', x: px + 8, y: py, vy: -5.5, t: 0 });
}
function spawnItem(kind, px, py) {
  Audio.sfx.appear();
  if (kind === 'mush' && mario.power > 0) kind = 'flower';
  Game.entities.push({ type: 'item', kind, x: px + 8, y: py + 16, w: 12, h: 14, vx: 0, vy: 0, rise: 16, anim: 0 });
}
const isEnemy = e => e.type === 'goomba' || e.type === 'koopa' || e.type === 'shell';

// ---------------- Entities ----------------
function spawnEnemies() {
  const edge = Game.camX + W + 24;
  for (const s of World.enemySpawns) {
    if (!s.spawned && s.tx * T < edge) {
      s.spawned = true;
      Game.entities.push({ type: s.type, x: s.tx * T + 8, y: 13 * T, w: 12, h: s.type === 'koopa' ? 24 : 16, vx: -0.55, vy: 0, anim: 0, dead: false, deadT: 0, kicked: 0 });
    }
  }
}
function flipKill(e, dir) {
  e.dead = true; e.flip = true; e.vy = -4; e.vx = dir * 1.5; e.deadT = 0;
  addScore(e.type === 'shell' ? 200 : 100, e.x, e.y - 16);
}
function stompKill(e) {
  if (e.type === 'goomba') { e.dead = true; e.flat = true; e.deadT = 0; e.vx = 0; addScore(100, e.x, e.y - 16); }
  else if (e.type === 'koopa') { e.type = 'shell'; e.h = 16; e.vx = 0; e.kicked = 0; e.idle = 0; addScore(100, e.x, e.y - 16); }
  else if (e.type === 'shell') { if (e.vx !== 0) { e.vx = 0; e.kicked = 0; e.idle = 0; addScore(100, e.x, e.y - 16); } }
  Audio.sfx.stomp();
}
function overlaps(a, b) {
  return Math.abs(a.x - b.x) < (a.w + b.w) / 2 && a.y > b.y - b.h && a.y - a.h < b.y;
}
function updateEntities() {
  const m = mario;
  const ents = Game.entities;
  for (const e of ents) {
    if (e.remove) continue;
    // offscreen cull (left side far behind, or fell)
    if (e.x < Game.camX - 64 || e.y > (LH + 2) * T) { if (e.type === 'fireball') m.fireballs--; e.remove = true; continue; }
    if (e.x > Game.camX + W + 48 && e.type !== 'item') { if (e.type === 'fireball') { m.fireballs--; e.remove = true; } continue; } // wait offscreen right

    if (e.dead) {
      e.deadT++;
      if (e.flat) { if (e.deadT > 30) e.remove = true; continue; }
      e.vy += 0.4; e.y += e.vy; e.x += e.vx; // flipped: fall through everything
      continue;
    }
    switch (e.type) {
      case 'goomba': case 'koopa': {
        e.vy = Math.min(4.5, e.vy + 0.4);
        const hit = moveX(e); if (hit) e.vx = -e.vx;
        moveY(e);
        e.anim++;
        break;
      }
      case 'shell': {
        e.vy = Math.min(4.5, e.vy + 0.4);
        const hit = moveX(e); if (hit) { e.vx = -e.vx; Audio.sfx.bump(); }
        moveY(e);
        if (e.vx !== 0) {
          // moving shell kills other enemies
          for (const o of ents) {
            if (o === e || !isEnemy(o) || o.dead || o.remove) continue;
            if (overlaps(e, o)) { flipKill(o, Math.sign(e.vx)); Audio.sfx.kick(); }
          }
        }
        break;
      }
      case 'item': {
        if (e.rise > 0) { e.y -= 0.5; e.rise -= 0.5; e.anim++; break; }
        if (e.kind === 'flower') { e.anim++; break; }
        if (e.kind === 'star') {
          e.vy = Math.min(4, e.vy + 0.22);
          if (e.vx === 0) { e.vx = 1.3; e.vy = -4; }
          const hit = moveX(e); if (hit) e.vx = -e.vx;
          if (moveY(e) === 'ground') e.vy = -4;
          e.anim++;
          break;
        }
        // mushroom / 1up
        e.vy = Math.min(4.5, e.vy + 0.4);
        if (e.vx === 0) e.vx = 1.0;
        const hit = moveX(e); if (hit) e.vx = -e.vx;
        moveY(e);
        break;
      }
      case 'fireball': {
        e.vy = Math.min(4, e.vy + 0.35);
        const hit = moveX(e);
        const r = moveY(e);
        if (r === 'ground') e.vy = -2.6;
        if (hit || (r && r.hit)) { explode(e); continue; }
        e.anim++;
        for (const o of ents) {
          if (!isEnemy(o) || o.dead || o.remove) continue;
          if (overlaps(e, o)) { flipKill(o, Math.sign(e.vx)); Audio.sfx.kick(); explode(e); break; }
        }
        break;
      }
    }
  }

  // Mario vs entities
  if (!m.dead && m.growT === 0 && m.shrinkT === 0 && Game.state === 'play') {
    for (const e of ents) {
      if (e.remove || e.dead) continue;
      if (!overlaps(m, e)) continue;
      if (e.type === 'item') {
        e.remove = true; powerUp(e.kind, e.x, e.y - 16); continue;
      }
      if (!isEnemy(e)) continue;
      if (m.star > 0) { flipKill(e, m.x < e.x ? 1 : -1); Audio.sfx.kick(); continue; }
      const falling = m.vy > 0 && (m.y - m.vy) <= e.y - e.h + 6;
      if (e.type === 'shell' && e.vx === 0) {
        // kick idle shell
