const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 800, height: 760 } });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  page.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') errors.push('CONSOLE: ' + m.text()); });
  await page.goto('file:///Users/ino/Develop/mario/fable5-1/index.html');
  await page.waitForTimeout(300);
  await page.screenshot({ path: '/tmp/mariotest/title.png' });
  await page.keyboard.press('Enter');
  await page.waitForTimeout(2300);
  await page.screenshot({ path: '/tmp/mariotest/play0.png' });
  // scripted play: run right, jump periodically
  const script = process.argv[2] || 'basic';
  const state = async () => page.evaluate(() => ({ st: Game.state, x: mario.x, y: mario.y, vx: mario.vx, vy: mario.vy, pow: mario.power, g: mario.onGround, score: Game.score, coins: Game.coins, lives: Game.lives, time: Game.time, ents: Game.entities.length, cam: Game.camX }));
  if (script === 'basic') {
    await page.keyboard.down('ArrowRight');
    for (let i = 0; i < 40; i++) {
      await page.keyboard.down('KeyX'); await page.waitForTimeout(250); await page.keyboard.up('KeyX');
      await page.waitForTimeout(400);
      const s = await state(); console.log(i, JSON.stringify(s));
      if (i % 8 === 0) await page.screenshot({ path: `/tmp/mariotest/p${i}.png` });
      if (s.st !== 'play') { await page.screenshot({ path: `/tmp/mariotest/end.png` }); break; }
    }
    await page.keyboard.up('ArrowRight');
  }
  console.log('errors:', errors);
  await browser.close();
})();

